import { z } from 'zod';
import { plainTextSchema, shortTextSchema } from '../core/rules';

/**
 * How alarms and reminders ring (lot 17a, decision FS): settings of the user, the same in every workspace (how long a
 * ring lasts, looped or once, rung again every N minutes until stopped, the ringtone, ringing outside the app), the bank
 * of ringtones generated by the app (Web Audio, no file), and the state of a ring (stopped, snoozed) kept by the API so
 * every tab and device, and the push notifications (lot 17c), follow it.
 */

/** Ringtones of the bank (generated by the app, no file), in the order offered. */
export const RINGTONES = [
  { id: 'carillon', label: 'Carillon' },
  { id: 'bip', label: 'Bip' },
  { id: 'marimba', label: 'Marimba' },
  { id: 'cloche', label: 'Cloche' },
  { id: 'reveil', label: 'Réveil' },
  { id: 'harpe', label: 'Harpe' },
] as const;

export type RingtoneId = (typeof RINGTONES)[number]['id'];

/** Ids of the ringtones. */
export const RINGTONE_IDS = RINGTONES.map((ringtone) => ringtone.id) as [RingtoneId, ...RingtoneId[]];

/**
 * Whether a value is a ringtone of the bank.
 * @param {unknown} value Value.
 * @returns {boolean} A ringtone.
 */
export function isRingtone(value: unknown): value is RingtoneId {
  return typeof value === 'string' && (RINGTONE_IDS as readonly string[]).includes(value);
}

/**
 * Label of a ringtone (« Carillon »).
 * @param {RingtoneId} id Ringtone.
 * @returns {string} Label.
 */
export function ringtoneLabel(id: RingtoneId): string {
  return RINGTONES.find((ringtone) => ringtone.id === id)?.label ?? id;
}

/** Longest ring, in minutes. */
export const RING_MINUTES_MAX = 30;

/** Longest time between two rings of the same alarm, in minutes. */
export const REPEAT_MINUTES_MAX = 60;

/** Settings of the rings of a user (every workspace). */
export type RingSettings = {
  /** How long a ring lasts, in minutes, unless stopped or snoozed. */
  ringMinutes: number;
  /** The ringtone repeats during the ring (else it plays once). */
  loop: boolean;
  /** Rung again this many minutes after a ring ends, until « Arrêter » (0: not again). */
  repeatMinutes: number;
  /** Ringtone of the reminders and alarms that name none. */
  ringtone: RingtoneId;
  /** Ring outside the app too (push notifications to the devices of the user, lot 17c). */
  outside: boolean;
};

/** Settings of a user who chose none. */
export const DEFAULT_RING_SETTINGS: RingSettings = { ringMinutes: 1, loop: true, repeatMinutes: 5, ringtone: 'carillon', outside: false };

/** Settings of the rings, as sent. */
export const ringSettingsSchema = z.object({
  ringMinutes: z.number().int().min(1, 'Au moins 1 minute.').max(RING_MINUTES_MAX, `${RING_MINUTES_MAX} minutes maximum.`),
  loop: z.boolean(),
  repeatMinutes: z.number().int().min(0, 'Au moins 0 minute.').max(REPEAT_MINUTES_MAX, `${REPEAT_MINUTES_MAX} minutes maximum.`),
  ringtone: z.enum(RINGTONE_IDS, 'Sonnerie inconnue.'),
  outside: z.boolean(),
});

/**
 * Settings of the rings read from a stored value: those of the defaults for what is missing or invalid.
 * @param {unknown} value Stored JSON (null: none chosen).
 * @returns {RingSettings} Settings.
 */
export function readRingSettings(value: unknown): RingSettings {
  const stored = value && typeof value === 'object' ? (value as Record<string, unknown>) : {};
  const settings = { ...DEFAULT_RING_SETTINGS };
  for (const key of Object.keys(DEFAULT_RING_SETTINGS) as (keyof RingSettings)[]) {
    const parsed = ringSettingsSchema.shape[key].safeParse(stored[key]);
    if (parsed.success) Object.assign(settings, { [key]: parsed.data });
  }
  return settings;
}

/** Minutes of « Répéter dans N min » without a repetition set. */
export const SNOOZE_FALLBACK_MINUTES = 5;

/**
 * Minutes of « Répéter dans N min »: those of the repetition, else 5.
 * @param {RingSettings} settings Settings.
 * @returns {number} Minutes.
 */
export function snoozeMinutes(settings: RingSettings): number {
  return settings.repeatMinutes || SNOOZE_FALLBACK_MINUTES;
}

/**
 * Next ring of an alarm that starts ringing: the repetition after the end of the ring, null without repetition.
 * @param {RingSettings} settings Settings.
 * @param {Date} ringingSince Start of the ring.
 * @returns {Date | null} Next ring.
 */
export function repeatedRingAt(settings: RingSettings, ringingSince: Date): Date | null {
  return settings.repeatMinutes ? new Date(ringingSince.getTime() + (settings.ringMinutes + settings.repeatMinutes) * 60_000) : null;
}

/** Alarms and reminders missed by more than this (app closed, server asleep) do not ring any more: 6 hours. */
export const RING_LATE_MS = 6 * 3600_000;

/** A ring not stopped stays this long after its last change (6 hours, as the reminders missed). */
export const RING_KEPT_MS = RING_LATE_MS;

/**
 * Whether an alarm or a reminder due at an instant rings now: due, and missed by 6 hours at most (`RING_LATE_MS`).
 * @param {Date} at Instant it is due.
 * @param {Date} now Now.
 * @returns {boolean} Rings now.
 */
export function isRingDue(at: Date, now: Date): boolean {
  const late = now.getTime() - at.getTime();
  return late >= 0 && late <= RING_LATE_MS;
}

/**
 * Line of a ring telling its workspace (« Espace « Perso » »), when it is not the one open (or rung by the server).
 * @param {string} label Label of the workspace.
 * @returns {string} Line.
 */
export const workspaceRingLine = (label: string): string => `Espace « ${label} »`;

// Push notifications (lot 17c, decision FU) -----------------------------------------------------------------------

/**
 * How long the server waits after an alarm or a reminder is due (or a ring to repeat) before it rings it outside the
 * app: an open app rings it first (it checks every 15 seconds) and the server then sees its ring and pushes nothing.
 */
export const PUSH_GRACE_MS = 30_000;

/** Longest label of a device. */
export const PUSH_LABEL_MAX = 120;

/** Longest address of a push service (endpoint of a device). */
export const PUSH_ENDPOINT_MAX = 2000;

/** Longest key of a device (base64url: `p256dh` is 87 characters, `auth` 22). */
export const PUSH_KEY_MAX = 200;

/**
 * Hosts of the Web Push services browsers subscribe to (Chrome / Android, Firefox, Safari, Edge): an endpoint must be
 * one of them or a sub-domain, since the server sends requests to it (no request to an address of the user's choice).
 */
export const PUSH_SERVICE_HOSTS = ['fcm.googleapis.com', 'updates.push.services.mozilla.com', 'push.apple.com', 'notify.windows.com'] as const;

/**
 * Whether a push endpoint is an https address of a known Web Push service (`PUSH_SERVICE_HOSTS`, sub-domains included).
 * @param {string} endpoint Endpoint of a subscription.
 * @returns {boolean} A known push service.
 */
export function isPushServiceEndpoint(endpoint: string): boolean {
  let url: URL;
  try {
    url = new URL(endpoint);
  } catch {
    return false;
  }
  if (url.protocol !== 'https:' || url.username || url.password || url.port) return false;
  const host = url.hostname.toLowerCase().replace(/\.$/, '');
  return PUSH_SERVICE_HOSTS.some((known) => host === known || host.endsWith(`.${known}`));
}

/** A device subscribing to the push notifications (`PushSubscription.toJSON()` of the browser, and its label). */
export const pushSubscriptionInputSchema = z.object({
  endpoint: z
    .url({ protocol: /^https$/ })
    .max(PUSH_ENDPOINT_MAX)
    .refine(isPushServiceEndpoint, 'Service de notifications inconnu.'),
  p256dh: z.string().min(1).max(PUSH_KEY_MAX),
  auth: z.string().min(1).max(PUSH_KEY_MAX),
  label: z.string().trim().max(PUSH_LABEL_MAX).transform((label) => label || 'Appareil'),
});

export type PushSubscriptionInput = z.input<typeof pushSubscriptionInputSchema>;

/** Action of a pushed notification (`notificationclick` of the service worker). */
export type PushAction = 'stop' | 'snooze';

/**
 * What the server pushes to a device (the service worker `public/push-sw.js` reads it): a ring to show, or a test.
 * The notification has the tag `ordo.alarm.<key>` (a resend replaces it, as the notification of the open app).
 */
export interface PushPayload {
  /** Key of the ring (without `ordo.alarm.`); null for a test. */
  key: string | null;
  title: string;
  /** Lines under the title, one per line. */
  body: string;
  /** Page of the app the notification opens, and its workspace. */
  path: string;
  workspaceId: string | null;
  /** Buttons of the notification (none for a test). */
  actions: { action: PushAction; title: string }[];
}

/**
 * Buttons of a pushed ring, as the toast of the app: « Arrêter », « Répéter dans N min ».
 * @param {RingSettings} settings Settings of the user.
 * @returns {PushPayload['actions']} Buttons.
 */
export function pushRingActions(settings: RingSettings): PushPayload['actions'] {
  return [
    { action: 'stop', title: 'Arrêter' },
    { action: 'snooze', title: `Répéter dans ${snoozeMinutes(settings)} min` },
  ];
}

/** Longest key of a ring. */
export const RING_KEY_MAX = 500;

/** Most lines under the title of a ring. */
export const RING_LINES_MAX = 5;

/** A ring as the app sends it when it starts ringing: what its toast shows, so another tab or device shows it too. */
export const alarmRingInputSchema = z.object({
  key: z.string().min(1).max(RING_KEY_MAX),
  workspaceId: z.string().nullish(),
  title: plainTextSchema,
  lines: z.array(plainTextSchema).max(RING_LINES_MAX).nullish().transform((lines) => lines ?? []),
  path: z.string().max(RING_KEY_MAX).startsWith('/').nullish(),
  linkLabel: shortTextSchema.nullish(),
  // A ringtone no longer in the bank: the one of the settings.
  ringtone: z.string().nullish().transform((ringtone) => (isRingtone(ringtone) ? ringtone : null)),
  dueAt: z.date(),
});

export type AlarmRingInput = z.input<typeof alarmRingInputSchema>;
